SET search_path TO hermes_outreach;
SELECT campaign, daily_send_cap, max_new_per_day, send_window_start, send_window_end, min_gap_seconds, timezone
FROM outreach_config;

parameters.jsCode:
const config = $('Outreach Config').first().json;
const inWindow = [];
for (const item of $input.all()) {
  const row = item.json;
  const tz = row.timezone || 'Europe/Berlin';
  const now = new Date();
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz,
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).formatToParts(now);
  const hour = parts.find(p => p.type === 'hour')?.value || '00';
  const minute = parts.find(p => p.type === 'minute')?.value || '00';
  const nowTime = `${hour}:${minute}:00`;
  const start = (row.send_window_start || '09:00:00').toString().slice(0, 8);
  const end = (row.send_window_end || '17:00:00').toString().slice(0, 8);
  if (nowTime >= start && nowTime <= end) {
    inWindow.push({ json: { ...row, outreach_config: config } });
  }
}
return inWindow;

const lead = $input.first().json;
const cfg = $('Outreach Config').first().json;
const step = String(lead.sequence_step ?? 0);
const angle = (cfg.angles && cfg.angles[step]) ? cfg.angles[step] : `Follow-up step ${step}`;
return [{ json: { ...lead, outreach: cfg, angle } }];

