    }
  ]
}

parameters.jsCode:
const lead = $('Attach Outreach Config').first().json;
const cfg = lead.outreach;
let subject = null;
let body = null;
try {
  const resp = $input.first().json;
  const text = (resp.content || []).map(c => c.text || '').join('');
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    subject = (parsed.subject || '').trim();
    body = (parsed.body || '').trim();
  }
} catch (e) {
  // fall through to template
}
if (!subject || !body) {
  const name = lead.first_name || 'there';
  const company = lead.company || 'your team';
  subject = `${cfg.offer} — quick note for ${company}`;
  body = `Hi ${name},\n\n${lead.angle}\n\n${cfg.offer}\n\n${cfg.cta}\n\nBest,\n${cfg.sender_name}`;
}
const footer = `\n\n---\n%unsubscribe_url%\n${cfg.impressum_line}`;
return [{ json: { ...lead, subject, body, html_body: body + footer } }];

const lead = $('Parse LLM or Fallback').first().json;
const mg = $input.first().json;
const providerMessageId = mg.id || mg['Message-Id'] || null;
return [{
  json: {
    state_id: lead.state_id,
    lead_id: lead.lead_id,
    campaign: lead.campaign,
    sequence_step: lead.sequence_step,
    provider_message_id: providerMessageId,
    recipient: lead.email,
    subject: lead.subject,
    body: lead.body,
  }
}];

